  "negative_patterns": [],
  "open_questions": [
    "What is the expected size of Integer and Cardinal in the target environment (x86_64 Linux)?"
  ],
  "positive_patterns": [
    {
      "snippet": "SizeOf(Integer) = SizeOf(Cardinal)",
      "why_it_matches": "This pattern directly tests whether Integer and Cardinal have the same size, which is a core requirement for consistent casting behavior in Delphi mode."
    }
  ],
  "rule_name": "delphi-integer-cardinal-size-consistency",
